{
  "title": "HCV Treatment Adherence Game",
  "perWatchSecond": 5,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "Adherence Determines Epidemic Fate",
      "goal": "Adjust treatment adherence to see its impact on the epidemic's course.",
      "control": {
        "parameter": "theta",
        "label": "Adherence Proportion",
        "lowEnd": "0 (no adherence)",
        "highEnd": "1 (full adherence)"
      },
      "watch": "cq",
      "whatIf": {
        "prompt": "What if adherence is doubled?",
        "parameter": "theta",
        "value": 1.0
      },
      "difference": {
        "compartment": "cq",
        "summary": "peak",
        "at": null,
        "time": 40,
        "relation": "lower",
        "by": 0.005
      },
      "effect": "With full adherence, the peak of chronically infected who quit treatment drops noticeably.",
      "prediction": {
        "prompt": "Predict the change in the peak of cq when adherence is doubled.",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": null,
      "carryForward": "Observe how adherence shifts the balance between treatment success and dropout."
    },
    {
      "kind": "background",
      "finding": 3,
      "title": "Synergy of Recovery and Adherence",
      "goal": "Explore how faster acute recovery together with higher adherence reduces transmission.",
      "control": {
        "parameter": "theta",
        "label": "Adherence Proportion",
        "lowEnd": "0 (no adherence)",
        "highEnd": "1 (full adherence)"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if both adherence is doubled and acute recovery rate is increased?",
        "parameter": "r2",
        "value": 0.326
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 40,
        "relation": "lower",
        "by": 0.01
      },
      "effect": "Combining full adherence with a higher acute recovery rate sharply lowers the peak of acute infections.",
      "prediction": {
        "prompt": "Predict the peak of acute infections when adherence is doubled and r2 is increased.",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Synergistic Impact",
        "quote": "Our model unraveled the synergistic impact of simultaneously enhancing the recovery rate of acutely infected individuals and treatment adherence on reducing $ℛ_{0}$."
      },
      "carryForward": "Notice the compounded effect on acute cases when both parameters improve."
    },
    {
      "kind": "idea",
      "finding": 4,
      "title": "Quitters Drive Transmission",
      "goal": "See how changes in the quitting rate affect the most infectious group.",
      "control": {
        "parameter": "delta",
        "label": "Quitting Rate",
        "lowEnd": "0 (no quitting)",
        "highEnd": "1.2 (high quitting)"
      },
      "watch": "cq",
      "whatIf": {
        "prompt": "What if the quitting rate is halved?",
        "parameter": "delta",
        "value": 0.3
      },
      "difference": {
        "compartment": "cq",
        "summary": "peak",
        "at": null,
        "time": 40,
        "relation": "lower",
        "by": 0.004
      },
      "effect": "Halving the quitting rate reduces the peak number of chronically infected who quit treatment.",
      "prediction": {
        "prompt": "Predict the change in the peak of cq when the quitting rate is halved.",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Transmission Risk",
        "quote": "$\\beta_{3}$ exerts the strongest influence on the reproduction number."
      },
      "carryForward": "Focus on interventions that lower the quitting rate to curb transmission."
    },
    {
      "kind": "method",
      "finding": 6,
      "title": "Speeding Chronic Recovery",
      "goal": "Test how a faster chronic recovery rate pushes the epidemic below the threshold.",
      "control": {
        "parameter": "rho",
        "label": "Chronic Recovery Rate",
        "lowEnd": "0.053 (baseline)",
        "highEnd": "0.19 (enhanced)"
      },
      "watch": "r",
      "whatIf": {
        "prompt": "What if the chronic recovery rate is set to 0.19?",
        "parameter": "rho",
        "value": 0.19
      },
      "difference": {
        "compartment": "r",
        "summary": "peak",
        "at": null,
        "time": 40,
        "relation": "higher",
        "by": 0.01
      },
      "effect": "Increasing the chronic recovery rate to 0.19 raises the peak of recovered individuals, indicating the epidemic falls below the threshold.",
      "prediction": {
        "prompt": "Predict the peak of recovered when rho is increased to 0.19.",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": {
        "title": "Recovery Threshold",
        "quote": "When $\\rho$ approaches a value of approximately 0.19, we observe that $\\mathcal{R}_{0}$ falls below 1."
      },
      "carryForward": "Observe how a higher recovery rate accelerates the move toward epidemic control."
    },
    {
      "kind": "evaluation",
      "finding": 2,
      "title": "Re‑infection's Minor Role",
      "goal": "Assess the impact of changing re‑susceptibility on the overall epidemic.",
      "control": {
        "parameter": "phi",
        "label": "Re‑susceptibility Rate",
        "lowEnd": "0 (none)",
        "highEnd": "0.002 (doubled)"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if re‑susceptibility is doubled?",
        "parameter": "phi",
        "value": 0.002
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 40,
        "relation": "higher",
        "by": 0.001
      },
      "effect": "Doubling re‑susceptibility causes only a slight rise in the peak of acute infections, confirming its minimal effect.",
      "prediction": {
        "prompt": "Predict the change in the peak of acute infections when phi is doubled.",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": {
        "title": "Minimal Impact",
        "quote": "variations in re-susceptibility minimally impact outcomes, suggesting that re-susceptibility can often be excluded in such analyses."
      },
      "carryForward": "Note that even substantial changes in re‑infection have little sway over the epidemic trajectory."
    }
  ],
  "limits": [
    "Each level runs for 40 time units, displayed at 5 steps per second, fitting within the 20‑second visibility window.",
    "Controls adjust only rate parameters (no starting values).",
    "What‑if changes are taken directly from the paper’s discussed thresholds or factor‑two modifications.",
    "Measured differences are clear on a chart scaled to the highest compartment value, showing at least a 10% separation.",
    "Predictions require the learner to state whether the What‑if world is higher or lower for the observed compartment."
  ]
}
